mkdir -p checks && cat > checks/service_checks.py <<'EOF'
import os, sys
sys.path.insert(0, os.getcwd())
import sqlite3
from src.repository import initialize, balance
from src.service import transfer
from src.events import Recorder


def fresh():
    c = sqlite3.connect(":memory:")
    initialize(c)
    c.executemany("INSERT INTO accounts VALUES (?, ?)", [("a", 100), ("b", 20)])
    c.commit()
    return c


def ledger(c):
    return c.execute("SELECT * FROM ledger").fetchall()


def expect_value_error(c, p, *args):
    before = (balance(c, "a"), balance(c, "b"), ledger(c))
    try:
        transfer(c, p, *args)
    except ValueError:
        pass
    else:
        raise AssertionError(f"expected ValueError for {args}")
    assert (balance(c, "a"), balance(c, "b"), ledger(c)) == before
    assert p.events == []


# invalid transfers
for args in [("a", "a", 1), ("a", "zz", 1), ("zz", "b", 1), ("a", "b", 0),
             ("a", "b", -1), ("a", "b", True), ("a", "b", 1.0),
             ("a", "b", "5"), ("a", "b", 101)]:
    c, p = fresh(), Recorder()
    expect_value_error(c, p, *args)

# successful transfer: one ledger row, exact balances, one event
c, p = fresh(), Recorder()
transfer(c, p, "a", "b", 100)
assert (balance(c, "a"), balance(c, "b")) == (0, 120)
assert ledger(c) == [("a", "b", 100)]
assert p.events == [{"source": "a", "target": "b", "amount": 100}]


class FailingConn:
    """Wraps a real connection and fails on the Nth execute or on commit."""
    def __init__(self, inner, fail_at=None, fail_commit=False):
        self.inner, self.n, self.fail_at, self.fail_commit = inner, 0, fail_at, fail_commit
        self.rolled_back = False

    def execute(self, sql, params=()):
        self.n += 1
        if self.fail_at == self.n:
            raise sqlite3.OperationalError("boom")
        return self.inner.execute(sql, params)

    def commit(self):
        if self.fail_commit:
            raise sqlite3.OperationalError("commit boom")
        self.inner.commit()

    def rollback(self):
        self.rolled_back = True
        self.inner.rollback()


# database failure at each write statement and at commit: rolled back, no publish
for kwargs in [dict(fail_at=1), dict(fail_at=2), dict(fail_at=3), dict(fail_commit=True)]:
    base = fresh()
    c = FailingConn(base, **kwargs)
    p = Recorder()
    try:
        transfer(c, p, "a", "b", 10)
    except sqlite3.OperationalError:
        pass
    else:
        raise AssertionError(f"expected DB failure for {kwargs}")
    assert c.rolled_back
    assert (balance(base, "a"), balance(base, "b")) == (100, 20), kwargs
    assert ledger(base) == [], kwargs
    assert p.events == [], kwargs


# publication failure propagates but the committed transfer stands
class BrokenPublisher:
    def publish(self, event):
        raise RuntimeError("publish down")


c = fresh()
try:
    transfer(c, BrokenPublisher(), "a", "b", 10)
except RuntimeError:
    pass
else:
    raise AssertionError("publication failure should propagate")
assert (balance(c, "a"), balance(c, "b")) == (90, 30)
assert ledger(c) == [("a", "b", 10)]

print("service checks passed")
EOF
